:square;stroke-width:2.3;\"></path>\n   </g>\n   <g id=\"line2d_2\">\n    <path clip-path=\"url(#pfe2031513c)\" d=\"M 39.986102 249.869614 \nL 249.817156 40.03856 \nL 249.817156 40.03856 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n  </g>\n </g>\n <defs>\n  <clipPath id=\"pfe2031513c\">\n   <rect height=\"260.82\" width=\"271.206637\" x=\"7.2\" y=\"7.2\"></rect>\n  </clipPath>\n </defs>\n</svg>\n<div role=\"region\" aria-label=\"Long description for graph of a system of 2 lines\" class=\"sr-only\"><ul><li>For the first line in the system:<br>\n<ul>\n<li>The line slants gradually down from left to right.</li>\n<li>The line passes through the following points:<br>\n<ul>\n<li>(0 comma 4)</li>\n<li>(2 comma 2)</li>\n<li>(4 comma 0)</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>For the second line in the system:<br>\n<ul>\n<li>The line slants gradually up from left to right.</li>\n<li>The line passes through the following points: <ul><li>(0 comma 0)</li><li>(2 comma 2)</li><li>(4 comma 4)</li></ul></li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">The graph of a system of two linear equations is shown. What is the solution <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> to the system?</p>","answerOptions":[{"id":"c13235a2-1439-4f60-a89b-c496841c1d19","content":"<p><math alttext=\"left parenthesis 0 comma 4 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mrow><mn>4</mn></mrow></mrow></mfenced></math></p>"},{"id":"998db47f-e399-49ff-b2cd-472a20781218","content":"<p><math alttext=\"left parenthesis 2 comma 2 right parenthesis\"><mfenced><mrow><mrow><mn>2</mn></mrow><mo>,</mo><mrow><mn>2</mn></mrow></mrow></mfenced></math></p>"},{"id":"a771e2d4-60fa-448b-8e8d-3bec3e98f7a0","content":"<p><math alttext=\"left parenthesis 4 comma 0 right parenthesis\"><mfenced><mrow><mrow><mn>4</mn></mrow><mo>,</mo><mn>0</mn></mrow></mfenced></math></p>"},{"id":"e7796e08-2881-4d63-b1cc-11de714b9b7a","content":"<p><math alttext=\"left parenthesis 4 comma 4 right parenthesis\"><mfenced><mrow><mrow><mn>4</mn></mrow><mo>,</mo><mrow><mn>4</mn></mrow></mrow></mfenced></math></p>"}],"keys":["998db47f-e399-49ff-b2cd-472a20781218"],"correct_answer":["B"],"rationale":"<p>Choice B is correct. The solution to this system of linear equations is represented by the point that lies on both lines shown, or the point of intersection of the two lines. According to the graph, the point of intersection occurs when <math alttext=\"x equals 2\"><mrow>\n<mi>x</mi>\n<mo>=</mo>\n<mn>2</mn>\n</mrow>\n</math> and <math alttext=\"y equals 2\"><mrow>\n<mi>y</mi>\n<mo>=</mo>\n<mn>2</mn>\n</mrow>\n</math>, or at the point <math alttext=\"left parenthesis 2 comma 2 right parenthesis\"><mfenced><mrow><mn>2</mn><mo>,</mo><mn>2</mn></mrow></mfenced></math>. Therefore, the solution <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> to the system is <math alttext=\"left parenthesis 2 comma 2 right parenthesis\"><mfenced><mrow><mn>2</mn><mo>,</mo><mn>2</mn></mrow></mfenced></math>.</p>\n<p>Choice A is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice C is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice D is incorrect and may result from conceptual or calculation errors.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1743430554982,"pPcc":"SAT#H","questionId":"f6b055dc","skill_cd":"H.D.","score_band_range_cd":1,"skill_desc":"Systems of two linear equations in two variables","createDate":1743430554982,"program":"SAT","primary_class_cd_desc":"Algebra","ibn":"","external_id":"58253567-9086-41df-86cd-17a48bbb725b","primary_class_cd":"H","uId":"c7c2e8d4-a04a-49e8-9c2d-5a